{
  "findings": [
    {
      "check_id": "CKV_GCP_82",
      "title": "Pub/Sub topic is not encrypted with Customer-Managed Key (CMK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic is not encrypted with a Customer-Managed Key (CMK), which may not meet data encryption requirements."
    }
  ],
  "patched_code": "resource "google_pubsub_topic" "notification_queue" {
  name = "insurance-claims-processing-platform-pubsub-notifications"
  labels = {
    environment = "production"
    component   = "notifications"
  }
  kms_key_name = google_kms_crypto_key.pubsub_key.id
}

resource "google_kms_key_ring" "pubsub_keyring" {
  name     = "insurance-claims-processing-platform-pubsub-keyring"
  location = "us-central1"
}

resource "google_kms_crypto_key" "pubsub_key" {
  name            = "insurance-claims-processing-platform-pubsub-key"
  key_ring        = google_kms_key_ring.pubsub_keyring.id
  rotation_period = "100000s"
}",
  "fix_summary": "Added a Customer-Managed Key (CMK) to encrypt the Pub/Sub topic, including a KMS key ring and crypto key with rotation period."
}
